//! Compiled-in PG 18.6 catalog objects (ARCHITECTURE §9): system relations with exact column
//! lists, builtin schemas/roles/databases/collations/access methods/languages, builtin
//! descriptions. Builtin TYPES / PROCS / OPERATORS / CASTS / AGGREGATES live in
//! `pgarbor_types::catalog_data` and are not duplicated here.
//!
//! `system_rels.rs`, `objects.rs` and `descriptions.rs` are GENERATED by
//! `python3 crates/pgarbor-catalog/gen/gen_builtin.py` (never edit by hand).
//!
//! Bootstrap-mutable objects: the `public` schema (2200), the `postgres` superuser (10) and the
//! `postgres` database (5) appear in the generated tables (as PG ships them) but are WRITTEN TO THE
//! BRANCH CATALOG at bootstrap (`persist::meta::bootstrap`) and from then on read only from storage,
//! so they can be altered, renamed or dropped. [`BOOTSTRAP_OIDS`] lists them; snapshot building
//! skips those generated rows.
//!
//! Everything in this module is fully implemented and frozen (v1).
use crate::model::{Column, RelKind, Relation, ViewDef};
use crate::model::StoredExpr;
use pgarbor_common::Oid;
use pgarbor_types::TypeId;
use std::collections::HashMap;
use std::sync::OnceLock;

pub mod descriptions;
pub mod objects;
pub mod ext_rows;
pub mod system_rels;

pub use descriptions::BUILTIN_DESCRIPTIONS;
pub use objects::*;
pub use system_rels::{relid, SYSTEM_RELS, SYSTEM_VIEW_DEFS};

/// pg_catalog namespace.
pub const PG_CATALOG_NAMESPACE: Oid = 11;
/// pg_toast namespace.
pub const PG_TOAST_NAMESPACE: Oid = 99;
/// public namespace (bootstrap-mutable).
pub const PUBLIC_NAMESPACE: Oid = 2200;
/// information_schema namespace.
pub const INFORMATION_SCHEMA_NAMESPACE: Oid = 13293;
/// Bootstrap superuser `postgres`.
pub const BOOTSTRAP_SUPERUSER: Oid = 10;
/// `pg_database_owner` predefined role (owner of `public`).
pub const PG_DATABASE_OWNER: Oid = 6171;
/// The `postgres` database.
pub const POSTGRES_DATABASE: Oid = 5;
/// `pg_default` tablespace.
pub const DEFAULT_TABLESPACE: Oid = 1663;
/// Languages.
pub const LANG_INTERNAL: Oid = 12;
pub const LANG_C: Oid = 13;
pub const LANG_SQL: Oid = 14;
pub const LANG_PLPGSQL: Oid = 13647;
/// Collations.
pub const DEFAULT_COLLATION: Oid = 100;
pub const C_COLLATION: Oid = 950;
/// Encoding id of UTF8.
pub const UTF8_ENCODING: i32 = 6;

/// Objects that are generated here but live in the branch catalog after bootstrap.
pub const BOOTSTRAP_OIDS: &[(crate::model::ObjClass, Oid)] = &[
    (crate::model::ObjClass::Namespace, PUBLIC_NAMESPACE),
    (crate::model::ObjClass::Role, BOOTSTRAP_SUPERUSER),
    (crate::model::ObjClass::Database, POSTGRES_DATABASE),
];

/// One column of a system relation (attnum > 0), exactly as PG 18.6's pg_attribute.
// CONTRACT
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SysCol {
    pub attnum: i16,
    pub name: &'static str,
    pub type_oid: Oid,
    pub typmod: i32,
    pub not_null: bool,
}

/// A system relation (pg_catalog / information_schema table, view or index).
// CONTRACT
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SystemRel {
    pub oid: Oid,
    pub name: &'static str,
    /// 11 (pg_catalog) or 13293 (information_schema).
    pub namespace: Oid,
    /// b'r' table, b'v' view, b'i' index.
    pub kind: u8,
    /// `reltype` (0 for indexes).
    pub rowtype: Oid,
    pub columns: &'static [SysCol],
}

