/// Rows of a builtin-only catalog in PG text-output form (NULL = None), columns in catalog order.
/// Producers convert each value with `pgarbor_types::io::input` using the column type from
/// [`system_rel`]`(rel)`.
// CONTRACT
#[derive(Clone, Copy, Debug)]
pub struct TextRows {
    pub rel: Oid,
    pub rows: &'static [&'static [Option<&'static str>]],
}

/// System relation by OID (binary search over [`SYSTEM_RELS`]).
pub fn system_rel(oid: Oid) -> Option<&'static SystemRel> {
    SYSTEM_RELS.binary_search_by_key(&oid, |r| r.oid).ok().map(|i| &SYSTEM_RELS[i])
}

/// System relation (any kind) by namespace OID and exact name.
pub fn system_rel_by_name(namespace: Oid, name: &str) -> Option<&'static SystemRel> {
    static MAP: OnceLock<HashMap<(Oid, &'static str), usize>> = OnceLock::new();
    let map = MAP.get_or_init(|| SYSTEM_RELS.iter().enumerate().map(|(i, r)| ((r.namespace, r.name), i)).collect());
    map.get(&(namespace, name)).map(|i| &SYSTEM_RELS[*i])
}

/// `pg_get_viewdef` text of a system view.
pub fn system_view_def(oid: Oid) -> Option<&'static str> {
    SYSTEM_VIEW_DEFS.binary_search_by_key(&oid, |v| v.0).ok().map(|i| SYSTEM_VIEW_DEFS[i].1)
}

/// The system tables and views (kinds 'r'/'v', not indexes) materialized as ordinary [`Relation`]s
/// (owner 10, columns with the type's collation, `view` filled for views), sorted by OID. The
/// binder resolves `pg_class`, `information_schema.columns`, ... through these exactly like user
/// relations; `Relation::is_virtual()` is true for all of them.
pub fn builtin_relations() -> &'static [Relation] {
    static RELS: OnceLock<Vec<Relation>> = OnceLock::new();
    RELS.get_or_init(|| {
        SYSTEM_RELS
            .iter()
            .filter(|r| r.kind == b'r' || r.kind == b'v')
            .map(|r| {
                let columns = r
                    .columns
                    .iter()
                    .map(|c| {
                        let coll = pgarbor_types::registry::lookup_type(c.type_oid).map(|t| t.collation).unwrap_or(0);
                        let mut col = Column::new(c.attnum, c.name, TypeId::new(c.type_oid, c.typmod), coll);
                        col.not_null = c.not_null;
                        col
                    })
                    .collect();
                let array_type = pgarbor_types::registry::lookup_type(r.rowtype).map(|t| t.array).unwrap_or(0);
                let kind = if r.kind == b'v' { RelKind::View } else { RelKind::Table };
                Relation {
                    oid: r.oid,
                    name: r.name.to_string(),
                    namespace: r.namespace,
                    kind,
                    owner: BOOTSTRAP_SUPERUSER,
                    persistence: Default::default(),
                    columns,
                    rowtype: r.rowtype,
                    array_type,
                    array_type_name: None,
                    options: Vec::new(),
                    acl: None,
                    replica_identity: if kind == RelKind::View {
                        crate::model::ReplicaIdentity::Nothing
                    } else {
                        crate::model::ReplicaIdentity::Default
                    },
                    row_security: false,
                    force_row_security: false,
                    policies: Vec::new(),
                    rules: Vec::new(),
                    view: system_view_def(r.oid).map(|d| ViewDef {
                        query: StoredExpr::new(d),
                        check_option: None,
                        populated: true,
                    }),
                    partition_key: None,
                    partition_of: None,
                    inherits: Vec::new(),
                }
            })
            .collect()
    })
}

/// Builtin relation (table/view) by OID.
pub fn builtin_relation(oid: Oid) -> Option<&'static Relation> {
    let rels = builtin_relations();
    rels.binary_search_by_key(&oid, |r| r.oid).ok().map(|i| &rels[i])
}

/// Builtin namespace by OID (excluding bootstrap-mutable `public`).
pub fn builtin_namespace(oid: Oid) -> Option<&'static BuiltinNamespace> {
    NAMESPACES.iter().find(|n| n.oid == oid && n.oid != PUBLIC_NAMESPACE)
}

/// Builtin role by OID (excluding bootstrap-mutable `postgres`).
pub fn builtin_role(oid: Oid) -> Option<&'static BuiltinRole> {
    ROLES.iter().find(|r| r.oid == oid && r.oid != BOOTSTRAP_SUPERUSER)
}

/// Builtin database by OID (excluding bootstrap-mutable `postgres`).
pub fn builtin_database(oid: Oid) -> Option<&'static BuiltinDatabase> {
    DATABASES.iter().find(|d| d.oid == oid && d.oid != POSTGRES_DATABASE)
}

/// Builtin collation by OID.
pub fn builtin_collation(oid: Oid) -> Option<&'static BuiltinCollation> {
    COLLATIONS.binary_search_by_key(&oid, |c| c.oid).ok().map(|i| &COLLATIONS[i])
}

/// Builtin description of (classoid, objoid), objsubid 0.
pub fn builtin_description(classoid: Oid, objoid: Oid) -> Option<&'static str> {
    BUILTIN_DESCRIPTIONS
        .binary_search_by(|(c, o, _)| (*c, *o).cmp(&(classoid, objoid)))
        .ok()
        .map(|i| BUILTIN_DESCRIPTIONS[i].2)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn system_rels_present() {
        let pg_class = system_rel(relid::PG_CLASS).unwrap();
        assert_eq!(pg_class.name, "pg_class");
        assert_eq!(pg_class.columns[0].name, "oid");
        assert_eq!(system_rel_by_name(INFORMATION_SCHEMA_NAMESPACE, "columns").unwrap().columns.len(), 44);
        assert!(builtin_relation(relid::PG_TABLES).unwrap().view.is_some());
        assert!(SYSTEM_RELS.windows(2).all(|w| w[0].oid < w[1].oid));
        assert_eq!(builtin_description(1255, 1242).is_some() || builtin_description(1247, 16).is_some(), true);
    }
}
